\label{def:strong-solution}
Let $\tau>0$, $v_0\in V$, and $T_0\in V_T$. A pair $(v,T)$ is a strong solution on $[0,\tau]$ if
\begin{align*}
v&\in L^\infty(0,\tau;V)\cap L^2(0,\tau;D(A)),&\partial_tv&\in L^2(0,\tau;H),\\
T&\in L^\infty(0,\tau;V_T),&\nabla_HT&\in L^2(0,\tau;H^1(\Omega)),\quad\partial_tT\in L^2(0,\tau;L^2(\Omega)),
\end{align*}
and the reformulated equations hold almost everywhere with the stated boundary and initial conditions.

\label{lem:linear-velocity}
\textbf{The velocity equation} Fixed $t_0$, and $\mathbf{v}^{n-1}$ is given in $X_{t_0}$ associated with $\mathbf{w^{n-1}}$ $\&$ ${T}^*$ is given in $T_{t_0}$, then the following equation has a unique solution $(v,w)$ with $v\in$ $X_{t_0}$.
\begin{align*}
\partial_t v + (\mathbf{v}^{n-1} \cdot \nabla_H) v + (\mathbf{w}^{n-1} \partial_z) v &+ \nabla_H p - \Delta v + f_0 k \times v = 0, \\
\partial_z p &+ T^* = 0, \\
\nabla_H \cdot \mathbf{v} &+ \partial_z \mathbf{w} = 0
\end{align*}

\label{thm:A^1/2 v}
Assume $(v_0,T_0)\in V\times V_T$. Then there exist a sufficiently small $t^*$ and a constant $K_2>0$, independent of $n$, such that
\begin{equation}
\sup_{0\le s\le t^*}
\|A^{1/2}v^n(s)\|_{L^2}^2
+
\int_0^{t^*}
\|Av^n(s)\|_{L^2}^2\,ds
\le K_2 .
\label{eq:uniform-vn-H1}
\end{equation}

\label{thm:H1 T}
Under the assumptions of Proposition~\ref{thm:A^1/2 v}, there exists a continuous nondecreasing function $K_3$ on $[0,t^*]$, independent of $n$, such that
\begin{equation}
\sup_{0\le s\le t^*}
\|\nabla T^n(s)\|_{L^2}^2
+
\int_0^{t^*}
\left(
\|\Delta_H T^n(s)\|_{L^2}^2
+
\|\nabla_H\partial_zT^n(s)\|_{L^2}^2
\right)\,ds
\le K_3(t^*).
\label{eq:uniform-Tn-H1}
\end{equation}

In $\Omega \times [0,t_0)$, with $v_0 \in V$ and $T_0 \in V_T$, there exists the following continuous functions $M_1, M_2, M_3$, such that, 
\begin{align*}
\sup_{0 \leq s \leq t} [\| v \|_6^2+\| \partial_zv \|_2^2] + \int_0^t \| \nabla u \|_2^2\leq M_1(t) \\
\sup_{0 \leq s \leq t} \| A^{1/2} v \|_2^2 + \int_0^t \| Av \|_H^2 \leq M_2(t) \\
\sup_{0 \le s \le t} \left(  \|\nabla T\|_2^2 \right) + \int_0^t  \|\nabla_H \nabla T\|_2^2  \le M_3(t)
\end{align*}

\label{prop:strong-solution-stability}
Let $t_0>0$, and let $(v^{(1)},T^{(1)})$ and
$(v^{(2)},T^{(2)})$ be two strong solutions on $[0,t_0]$ in the
sense of Definition~\ref{def:strong-solution}, with initial data
$(v_0^{(1)},T_0^{(1)})$ and $(v_0^{(2)},T_0^{(2)})$ in
$V\times V_T$, respectively. Define
\begin{equation}
\label{eq:coupled-stability-coefficient}
\begin{split}
G(t):=C\Bigl[&1+
 \bigl(1+\|v^{(2)}(t)\|_{H^1}^2\bigr)
          \|v^{(2)}(t)\|_{H^2}^2
 +\|\nabla_HT^{(2)}(t)\|_{H^1}^2\\
 &+\|\partial_zT^{(2)}(t)\|_2^2
 \bigl(\|\partial_zT^{(2)}(t)\|_2^2
       +\|\nabla_H\partial_zT^{(2)}(t)\|_2^2\bigr)\Bigr]
\end{split}
\end{equation}
where $C$ depends only on $\Omega$. Then $G\in L^1(0,t_0)$ and, for every $0\leq t\leq t_0$, we have 
\begin{equation}
\label{eq:coupled-strong-stability}
\begin{split}
 &\|v^{(1)}(t)-v^{(2)}(t)\|_2^2
       +\|T^{(1)}(t)-T^{(2)}(t)\|_2^2\\
 &\quad+\int_0^t\Bigl(
       \|\nabla(v^{(1)}-v^{(2)})\|_2^2
       +\|\nabla_H(T^{(1)}-T^{(2)})\|_2^2\Bigr)\,ds\\
 &\qquad\leq
 \Bigl(\|v_0^{(1)}-v_0^{(2)}\|_2^2
          +\|T_0^{(1)}-T_0^{(2)}\|_2^2\Bigr)
       \exp\!\left(\int_0^tG(s)\,ds\right).
\end{split}
\end{equation}
In particular, the coupled strong solution is unique and depends
continuously on its initial data in the $L^2$ energy norm.

\noindent
The Sobolev embeddings and the product rule give
\begin{align}
\|(v\cdot\nabla_H)v\|_{H^1}
\leq
C\left(
 \|v\|_\infty\|\nabla_Hv\|_{H^1}
 +\|\nabla v\|_4\|\nabla_Hv\|_4
\right)
\nonumber\leq C\|v\|_{H^2}^2.
\label{eq:horizontal-convection-H1}
\end{align}
Consequently,
\[
(v\cdot\nabla_H)v
\in L^\infty(0,t_0;H^1(\Omega))
\subset L^2(0,t_0;H^1(\Omega)).
\]

Since $u=\partial_zv$ and $w=\int_{-h}^z-\nabla_H\cdot v$, we also have
\[
\|u\|_{H^1}\leq C\|v\|_{H^2}, \qquad \|w\|_{H^1}
\leq C\|v\|_{H^2}.
\]
By the product rule and the embeddings,
\begin{equation}
\begin{aligned}
\|w\partial_zv\|_{H^{2/5}}
&\leq C\|wu\|_{W^{1,3/2}}\\
&\leq C\bigl(\|w\|_6\|u\|_2
 +\|\nabla w\|_2\|u\|_6
 +\|w\|_6\|\nabla u\|_2\bigr)\\
&\leq C\|w\|_{H^1}\|u\|_{H^1}
 \leq C\|v\|_{H^2}^2.
\end{aligned}
\label{eq:vertical-convection-H25}
\end{equation}
By the definition of $Q_T$ in \eqref{eq: Q}, $\|\nabla_H Q_T\|_{H^1}
\leq C\|\nabla_HT\|_{H^1}$,
Hence
\begin{align}
\nabla_H Q_T\in L^2(0,t_0;H^1(\Omega)).
\label{eq:Q-H1-estimate}
\end{align}



Rewrite the momentum equation as
\begin{equation}
-\Delta v+\nabla_Hp_s=F,
\label{eq:velocity-Stokes-equation}
\end{equation}
where
\[
F:=
-v_t-(v\cdot\nabla_H)v-w\partial_zv
-f_0k\times v+\nabla_H Q_T .
\]
By Proposition~\ref{prop:time-derivative-L2},
\eqref{eq:horizontal-convection-H1},
\eqref{eq:vertical-convection-H25},
\eqref{eq:Q-H1-estimate}, and Proposition~\ref{prop:velocity-H2},
\begin{equation}
F\in L^2(0,t_0;H^{2/5}(\Omega)).
\label{eq:F-H25}
\end{equation}
More precisely,
\begin{equation}
\|F\|_{H^{2/5}}
\leq
C\left(
 \|v_t\|_{H^1}
 +\|\nabla_HT\|_{H^1}
 +\|v\|_{H^2}
 +\|v\|_{H^2}^2
\right).
\label{eq:F-H25-bound}
\end{equation}

Fix \(0<\delta_0<1/6\), and let \(\mathcal S\) denote the velocity
component of the hydrostatic Stokes solution operator with the
prescribed boundary conditions. Lemmas~\ref{lem:top-stokes-H2}
and~\ref{lem:top-stokes-higher} give
\[
\mathcal S:L^2(\Omega)\longrightarrow H^2(\Omega),
\qquad
\mathcal S:H^1(\Omega)\longrightarrow H^{3-\delta_0}(\Omega).
\]
Complex interpolation yields
\[
\mathcal S:
\bigl[L^2(\Omega),H^1(\Omega)\bigr]_{2/5}
\longrightarrow
\bigl[H^2(\Omega),H^{3-\delta_0}(\Omega)\bigr]_{2/5}.
\]
By Lemma~\ref{lemma:Gagliardo}\textup{(ii)},
\[
\begin{aligned}
\bigl[L^2(\Omega),H^1(\Omega)\bigr]_{2/5}
&=H^{2/5}(\Omega),\\
\bigl[H^2(\Omega),H^{3-\delta_0}(\Omega)\bigr]_{2/5}
&=H^{s_*}(\Omega)\hookrightarrow H^{7/3}(\Omega),
\end{aligned}
\]
where \(s_*:=2+\frac25(1-\delta_0)>\frac73\). Therefore,
\[
\|v\|_{H^{7/3}}
\leq C\|v\|_{H^{s_*}}
\leq C\|F\|_{H^{2/5}}.
\]
Using \eqref{eq:F-H25}, we conclude that
\begin{equation}
v\in L^2(0,t_0;H^{7/3}(\Omega)).
\label{eq:v-H73}
\end{equation}
Using \(w=-\int_{-h}^z\nabla_H\cdot v(\xi)\,d\xi\),
\(\partial_zw=-\nabla_H\cdot v\), and the embedding
\(H^{4/3}(M)\hookrightarrow L^\infty(M)\cap W^{1,3}(M)\), we obtain
\begin{equation}
\begin{aligned}
\|w\|_\infty+\|\nabla w\|_3
&\leq C\Bigl(
 \|\nabla_H\cdot v\|_{L^2_zH^{4/3}(M)}
 +\|\nabla_H\cdot v\|_3\Bigr)\\
&\leq C\|v\|_{H^{7/3}}.
\end{aligned}
\label{eq:w-anisotropic-H73}
\end{equation}
Using the product rule,
\begin{align}
\|w\partial_zv\|_{H^1}
&\leq
C\left(
 \|w\|_\infty\|u\|_{H^1}
 +\|\nabla w\|_3\|u\|_6
\right)
\nonumber\\
&\leq
C\|v\|_{H^{7/3}}\|v\|_{H^2}.
\label{eq:vertical-convection-final-H1}
\end{align}
Then,
\begin{equation}
w\partial_zv\in L^2(0,t_0;H^1(\Omega)).
\label{eq:vertical-convection-L2H1}
\end{equation}
Returning to the definition of \(F\), we now have
\[
F\in L^2(0,t_0;H^1(\Omega)).
\]
with
\begin{align}
\|F\|_{H^1}
\leq C\Big(
 &\|v_t\|_{H^1}
 +\|\nabla_HT\|_{H^1}
 +\|v\|_{H^2}
 \nonumber+\|v\|_{H^2}\|v\|_{H^{7/3}}
\Big),
\label{eq:F-final-H1}
\end{align}
and every term on the right-hand side is $L^2$ in time

For every fixed \(\varepsilon\in(0,1)\), the higher hydrostatic
Stokes estimate in Lemma~\ref{lem:top-stokes-higher}, applied to
\eqref{eq:velocity-Stokes-equation} yields, for almost every time,
\begin{equation}
\begin{split}
\|v\|_{H^{3-\varepsilon}}
+\|\partial_zv\|_{H^{2-\varepsilon}}
+\|\nabla_Hp_s\|_{H^{1-\varepsilon}(M)}
\leq C_\varepsilon\|F\|_{H^1}.
\end{split}
\label{eq:final-higher-Stokes}
\end{equation}
Squaring \eqref{eq:final-higher-Stokes} and integrating in time gives
\[
v\in L^2(0,t_0;H^{3-\varepsilon}(\Omega)).
\]

\label{prop:horizontal-T-higher-reg}
Let $(v,T)$ be the strong solution of Theorem~\ref{thm:global-well-posedness}, with $v_0\in D(A)$ and $T_0\in H^2(\Omega)\cap V_T$. For every $0<t<\mathcal T^*$,
\begin{equation}
 \nabla_HT\in L^2(0,t;H^2(\Omega)).
 \label{eq:gradHT-H2eps}
\end{equation}
Moreover, there exists a continuous nondecreasing function $M_8$, finite on compact subintervals of $[0,\mathcal T^*)$, such that
\begin{equation}
 \int_0^t\|\nabla_HT(s)\|_{H^2(\Omega)}^2\,ds
 \leq M_8(t).
 \label{eq:gradHT-H2eps-est}
\end{equation}

Fix $0<t<\mathcal T^*$. Propositions~\ref{prop:horizontal-temperature-L2} and \ref{prop:Tzz-estimate} give $\Delta_HT,\partial_z^2T\in L^\infty(0,t;L^2)$. Horizontal Dirichlet elliptic regularity and Lemma~\ref{lem:anisotropic-isotropic} with $s=2$, applied to $T$, therefore yield
\[
 \|T\|_{H^2}
 \leq C\bigl(\|\Delta_HT\|_2+\|T\|_{H^1}
                            +\|\partial_z^2T\|_2\bigr).
\]
this proves $T\in L^\infty(0,t;H^2)$. Proposition~\ref{prop:velocity-higher-spatial}, with $\varepsilon=1/2$, also gives $v\in L^2(0,t;H^{5/2})$.

On the two-dimensional domain $M$, for $0<\varepsilon<1$ we have
\begin{equation}
 \begin{aligned}
 \|fg\|_{H^{1-\varepsilon}(M)}
 &\leq C_\varepsilon\|f\|_{H^1(M)}\|g\|_{H^1(M)},\\
 \|fg\|_{H^1(M)}
 &\leq C\|f\|_{H^{3/2}(M)}\|g\|_{H^1(M)}.
 \end{aligned}
 \label{eq:2d-product}
\end{equation}
The second inequality follows from the product rule and the embeddings $H^{3/2}(M)\hookrightarrow L^\infty(M)\cap W^{1,4}(M)$ and $H^1(M)\hookrightarrow L^4(M)$. The embedding $H^{5/2}(\Omega)\hookrightarrow H^1_zH^{3/2}_H$, the one-dimensional Sobolev embedding in $z$, 
\[
 \|v\|_{L^\infty_zH^{3/2}_H}
 +\|w\|_{L^\infty_zH^{3/2}_H}
 \leq C\|v\|_{H^{5/2}}.
\]
Using the second inequality in \eqref{eq:2d-product} on each
horizontal slice, we obtain
\[
 \|v\cdot\nabla_HT+w\partial_zT\|_{L^2_zH^1_H}
 \leq C\|v\|_{H^{5/2}}\|\nabla T\|_{L^2_zH^1_H}
 \leq C\|v\|_{H^{5/2}}\|T\|_{H^2}.
\]
The right-hand side belongs to $L^2(0,t)$.
Proposition~\ref{prop:time-derivative-L2} gives
$T_t\in L^2(0,t;L^2_zH^1_H)$. The temperature equation thus implies
\[
 \|\Delta_HT\|_{L^2_zH^1_H}
 \leq\|T_t\|_{L^2_zH^1_H}
        +C\|v\|_{H^{5/2}}\|T\|_{H^2}
 \in L^2(0,t).
\]
Applying horizontal Dirichlet elliptic regularity to $T$ yields
\[
 \|\nabla_HT\|_{L^2_zH^2_H}
 \leq C\bigl(\|\Delta_HT\|_{L^2_zH^1_H}+\|T\|_2\bigr)
 \in L^2(0,t).
\]
Only the original lateral condition on $T$ enters this elliptic step.
Finally, Lemma~\ref{lem:anisotropic-isotropic} with $s=2$, applied
componentwise to $\nabla_HT$, gives
\[
 \|\nabla_HT\|_{H^2}
 \leq C\bigl(\|\nabla_HT\|_{L^2_zH^2_H}
             +\|T\|_{H^2}+\|\nabla_H\partial_z^2T\|_2\bigr).
\]
Consequently,
\begin{align*}
 \int_0^t\|\nabla_HT\|_{H^2}^2\,ds
 \leq C\Bigg[&\int_0^t\|T_t\|_{L^2_zH^1_H}^2\,ds\\
 &+\|T\|_{L^\infty(0,t;H^2)}^2
       \left(t+\int_0^t\|v\|_{H^{5/2}}^2\,ds\right)\\
 &+\int_0^t\|\nabla_H\partial_z^2T\|_2^2\,ds\Bigg].
\end{align*}
All terms on the right are controlled by the preceding estimates;
the last one is bounded by Proposition~\ref{prop:Tzz-estimate}.
Their continuous nondecreasing majorants supply $M_8$ and prove
\eqref{eq:gradHT-H2eps-est}.

For constant depth $h\equiv h_0$, we have $a=0$ and $K_h=\operatorname{diag}(1,1,0)$, so
\begin{equation}
  \Delta_{H,h}^{\mathrm{top}}=\Delta_H.
  \label{eq:constant-depth-consistency}
\end{equation}

\label{prop:topographic-strong-stability}
Let $(v^{(i)},\theta^{(i)})$, $i=1,2$, be solutions of
\eqref{eq:topographic-coupled-system} on $[0,t_0]$, satisfying the
prescribed velocity and lateral temperature boundary conditions
and having the Sobolev regularity listed in
Theorem~\ref{prop:varying-bottom-main}\textup{(i)} on this interval.
For a sufficiently large geometric constant $C_h$, let
\begin{equation}
\begin{split}
 \Lambda_h[v^{(2)},\theta^{(2)}]=C_h\bigl[&
 1+\|v^{(2)}\|_{H^1}^4+\|\theta^{(2)}\|_{H^1}^4\\
 &+(1+\|v^{(2)}\|_{H^1}^2)\|v^{(2)}\|_{H^2}^2\\
 &+(1+\|\theta^{(2)}\|_{H^1}^2)
                         \|\nabla_H\theta^{(2)}\|_{H^1}^2\bigr].
\end{split}
\label{eq:topographic-stability-coefficient}
\end{equation}
Then $\Lambda_h[v^{(2)},\theta^{(2)}]\in L^1(0,t_0)$ and,
for every $0\leq t\leq t_0$,
\begin{equation}
\begin{split}
 &\|v^{(1)}(t)-v^{(2)}(t)\|_{2,h}^2
       +\|\theta^{(1)}(t)-\theta^{(2)}(t)\|_{2,h}^2\\
 &\quad+\int_0^t\mathfrak a_{v,h}
       \bigl(v^{(1)}(s)-v^{(2)}(s),
             v^{(1)}(s)-v^{(2)}(s)\bigr)\,ds\\
 &\quad+\int_0^t
       \|\nabla_H(\theta^{(1)}(s)-\theta^{(2)}(s))\|_{2,h}^2\,ds\\
 &\leq\Bigl(\|v^{(1)}(0)-v^{(2)}(0)\|_{2,h}^2
       +\|\theta^{(1)}(0)-\theta^{(2)}(0)\|_{2,h}^2\Bigr)\\
 &\qquad\times\exp\!\left(\int_0^t
                  \Lambda_h[v^{(2)},\theta^{(2)}](s)\,ds\right).
\end{split}
 \label{eq:topographic-strong-stability}
\end{equation}
In particular, the solution is unique in this class and depends
continuously on its initial data in the weighted $L^2$ energy norm.

\label{prop:top-time-derivative-L2}
Assume the hypotheses of the $H^1$ theory in Subsection~\ref{subsec:H1-varying-bottom}, and suppose in addition that $v^{\mathrm{phys}}_0\in H^2(\Omega_h)^2\cap V_h$ satisfies the homogeneous top stress condition, and that $T_0\in H^2(\Omega_h)\cap V_{T,h}$. Let $v_0=v^{\mathrm{phys}}_0\circ\Phi$ and $\theta_0=T_0\circ\Phi$. Then there exists a continuous nondecreasing function $M_{4,h}$, finite on every finite time interval, such that
\begin{equation}
 \begin{split}
 &\mathop{\mathrm{ess\,sup}}_{0<s<t}
   \left(\|v_t(s)\|_{2,h}^2+\|\theta_t(s)\|_{2,h}^2\right)\\
 &\quad+\int_0^t
   \left(\mathfrak a_{v,h}(v_t,v_t)
              +\|\nabla_H\theta_t\|_{2,h}^2\right)\,ds
 \leq M_{4,h}(t).
 \end{split}
 \label{eq:top-time-main}
\end{equation}
Equivalently, in physical coordinates,
\begin{equation}
 \begin{split}
 &\mathop{\mathrm{ess\,sup}}_{0<s<t}
   \left(\|\partial_t v^{\mathrm{phys}}(s)\|_{L^2(\Omega_h)}^2
                 +\|T_t(s)\|_{L^2(\Omega_h)}^2\right)\\
 &\quad+\int_0^t
   \left(\|\nabla\partial_t v^{\mathrm{phys}}\|_{L^2(\Omega_h)}^2
                 +\|X^hT_t\|_{L^2(\Omega_h)}^2\right)\,ds
 \leq M_{4,h}(t),
 \end{split}
 \label{eq:top-time-physical}
\end{equation}
where $X^h$ is the topographic horizontal gradient defined in
Subsection~\ref{subsec:topographic-notation}.

\label{anisotropic inequality}
(See \cite{https://doi.org/10.1002/cpa.10056} or \cite{CAO20144108}.)
Let $h>0$ be the constant depth. For functions $f,g,\varphi$
on $\Omega=M\times(-h,0)$ such that the right-hand sides below
are finite, the following inequalities hold:
\begin{align*}
&\int_M
 \left(\int_{-h}^0 f(x,y,z)\,dz\right)
 \left(\int_{-h}^0 g(x,y,z)\varphi(x,y,z)\,dz\right)\,dx\,dy\\
&\quad\leq
 C\|f\|_2^{1/2}
 \bigl(\|f\|_2^{1/2}+\|\nabla_Hf\|_2^{1/2}\bigr)
 \|g\|_2\|\varphi\|_2^{1/2}
 \bigl(\|\varphi\|_2^{1/2}
       +\|\nabla_H\varphi\|_2^{1/2}\bigr),
\end{align*}
and
\begin{align*}
&\int_M
 \left(\int_{-h}^0 f(x,y,z)\,dz\right)
 \left(\int_{-h}^0 g(x,y,z)\varphi(x,y,z)\,dz\right)\,dx\,dy\\
&\quad\leq
 C\|f\|_2\|g\|_2^{1/2}
 \bigl(\|g\|_2^{1/2}+\|\nabla_Hg\|_2^{1/2}\bigr)
 \|\varphi\|_2^{1/2}
 \bigl(\|\varphi\|_2^{1/2}
       +\|\nabla_H\varphi\|_2^{1/2}\bigr).
\end{align*}

\label{lemma:Gagliardo}
\noindent\textup{(i) Gagliardo--Nirenberg interpolation inequality.}
(see \cite{BREZIS20181355})Let $\Omega \subset \mathbb{R}^n$ be either the whole space, a half-space or a bounded Lipschitz domain. Let $1 \leq p, p_1, p_2 \leq +\infty$ be three positive extended real quantities and let $s, s_1, s_2$ be non-negative real numbers. Furthermore, let $\theta \in (0, 1)$ and assume that
\[
s_1 \leq s_2, \qquad s = \theta s_1 + (1 - \theta)s_2, \qquad \frac{1}{p} = \frac{\theta}{p_1} + \frac{1 - \theta}{p_2}
\]
hold. Then,
\[
\|u\|_{W^{s,p}(\Omega)} \leq C \|u\|_{W^{s_1,p_1}(\Omega)}^{\theta} \|u\|_{W^{s_2,p_2}(\Omega)}^{1-\theta}
\]
for any $u \in W^{s_1,p_1}(\Omega) \cap W^{s_2,p_2}(\Omega)$ if and only if
\[
\text{at least one of }
\begin{cases}
s_2 \in \mathbb{N} \text{ and } s_2 \geq 1, \\
p_2 = 1, \\
0 < s_2 - s_1 \leq 1 - \frac{1}{p_1}
\end{cases}
\text{ is false.}
\]
The constant $C > 0$ depends on the parameters $p, p_1, p_2, s, s_1, s_2, \theta$, on the domain $\Omega$, but not on $u$.

\medskip
\noindent\textup{(ii) Complex interpolation on bounded domains.}
Let $D\subset\mathbb R^n$ be a bounded Lipschitz domain. Let
$s_0,s_1\geq0$ with $s_0\neq s_1$, $1<p_0,p_1<\infty$, and
$0<\theta<1$, and set
\[
 s=(1-\theta)s_0+\theta s_1,\qquad
 \frac1p=\frac{1-\theta}{p_0}+\frac{\theta}{p_1}.
\]
Then
\begin{equation}
 [H_{p_0}^{s_0}(D),H_{p_1}^{s_1}(D)]_\theta=H_p^s(D)
 \label{eq:bounded-domain-complex-interpolation}
\end{equation}
with equivalent norms. Here $[\cdot,\cdot]_\theta$ denotes complex
interpolation, and $H_p^s(D)$ is the Bessel potential space defined
by restriction from $H_p^s(\mathbb R^n)$. These are the full spaces,
with no boundary trace conditions imposed.

In particular, if $m_0,m_1\in\mathbb N_0$, $m_0<m_1$, and
$(1-\theta)/p_0+\theta/p_1=1/2$, then
\begin{equation}
 [W^{m_0,p_0}(D),W^{m_1,p_1}(D)]_\theta
 =H^{(1-\theta)m_0+\theta m_1}(D)
 \label{eq:bounded-domain-integer-interpolation}
\end{equation}
with equivalent norms. We use here the integer-order identification
$H_p^m(D)=W^{m,p}(D)$ for $m\in\mathbb N_0$ and $1<p<\infty$,
and the identity $H_2^s(D)=H^s(D)$.

\label{lem:top-stokes-H2}
For $f\in L^2(\Omega_h)^2$,
\begin{equation}
 \|v\|_{H^2(\Omega_h)}
 +\|p_s\|_{H^1(M)}\leq C_h\|f\|_{L^2(\Omega_h)}.
 \label{eq:top-stokes-H2}
\end{equation}
Here $C_h$ depends only on $M$ and $h$.
This conclusion does not require \eqref{eq:top-stokes-orthogonal}.
In particular, it also applies when $h(x,y)\equiv h_0>0$ is constant,
in which case $\Omega_h=M\times(-h_0,0)$.

\label{lem:regularity}
\label{lem:top-stokes-higher}
Under the geometric assumptions of Lemma~\ref{lem:top-stokes-H2}, assume
in addition that
\[
 \partial_\nu h=0\qquad\text{on }\partial M,
\]
where $\nu$ is the horizontal outward unit normal. This is condition
\eqref{eq:top-stokes-orthogonal}: the bottom and sidewall meet at right
angles along their common edge. The top--sidewall junction is
automatically orthogonal.
For $f\in H^1(\Omega_h)^2$ and every $0<\varepsilon<1$, 
\begin{equation}
 \begin{split}
 &\|v\|_{H^{3-\varepsilon}(\Omega_h)}
 +\|\partial_zv\|_{H^{2-\varepsilon}(\Omega_h)}\\
 &\hspace{25mm}
 +\|\nabla_Hp_s\|_{H^{1-\varepsilon}(M)}
 \leq C_{h,\varepsilon}\|f\|_{H^1(\Omega_h)}.
 \end{split}
 \label{eq:top-stokes-higher}
\end{equation}
